    {q:"Which sentence uses a simile to describe speed?", options:["He was lightning.","He ran as fast as lightning.","He was very fast.","He ran quickly."], answer:1},
    {q:"Why might a metaphor be considered a stronger comparison than a simile?", options:["It only appears in poetry","It never compares anything","It states directly that one thing is another","It always uses the word like"], answer:2},
    {q:"Which of these is a common simile phrase?", options:["a mouse of silence","mouse-like silence only","the silent mouse","as quiet as a mouse"], answer:3},
    {q:"Which sentence best shows figurative rather than literal language?", options:["The sky was dark.","There were many stars.","The stars danced across the sky.","The stars are in the sky at night."], answer:2},
    {q:"Why is understanding figurative language important when reading?", options:["It has no effect on understanding a text","It helps readers understand meaning beyond the literal words","Figurative language always means exactly what it says","It is only used in textbooks, never in stories"], answer:1}
